import{_ as i,l as o,o as e,c as s,v as r,p as l,x as t,d as u,i as h,S as E}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"幸存者偏差","description":"","frontmatter":{"title":"幸存者偏差","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/survivorship-bias.md","filePath":"quant/survivorship-bias.md","lastUpdated":1789023840000}'),p={name:"quant/survivorship-bias.md"};function B(d,a,m,c,S,A){const n=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="幸存者偏差" tabindex="-1">幸存者偏差 <a class="header-anchor" href="#幸存者偏差" aria-label="Permalink to &quot;幸存者偏差&quot;">​</a></h1><div class="epigraph"><p>只研究仍然存在的基金或股票，等于按结果筛选样本；平均业绩会被向上推，消失者承担的那一段亏损从历史上被抹掉。</p><footer>—— 对照 Brown, Goetzmann, Ibbotson and Ross, Survivorship Bias in Performance Studies, RFS 1992</footer></div><p><a href="/quant/stress-reverse-stress">上一课</a>问极端情景怎么设。缺口是研究样本本身：你看到的截面，往往已经筛选过活下来的对象。回测与业绩评价默认你看到的截面，就是当时可投资的截面。幸存者偏差打破这个默认：数据库往往只留下活到今天的基金、活到样本期末的股票、活到指数里的成份。Brown、Goetzmann、Ibbotson 与 Ross（1992）证明，对业绩研究而言，这种筛选会系统性地抬高平均收益、压低风险。Malkiel（1995）、Elton–Gruber–Blake（1996）、Carhart–Carpenter–Lynch–Musto（2002）在共同基金上给出量级；Shumway（1997）指出 CRSP 退市收益缺失会让小盘与困境股的平均收益被高估。量化研究里，它不只是「基金排行榜」的问题：任何从今天的股票池往回生成因子，都在用幸存者讲过去。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>设 \\(t=0\\) 有 \\(N\\) 只基金（或股票），到 \\(T\\) 只剩 \\(N_s\\) 只。若消失的原因与收益相关——业绩差被清盘、股票退市、基金合并进更好看的系列——则对 \\(N_s\\) 的平均收益 \\(\\bar r_s\\) 高于对全样本路径的平均。Brown 等人还指出更细的扭曲：条件于生存，收益的横截面离散与真实技能的推断都会变。看起来「显著跑赢」的经理，有一部分只是没死在样本里。</p><p>股票侧，CRSP 对退市日若缺收益，研究者用最后一个可用价格结束，等于假设退市那天收益为零。Shumway 用 OTC 与事件数据补退市收益，发现绩效相关退市（破产等）平均是大幅负收益，缺省处理会让以小盘、低价、高账面市值比为重的策略显得更好。这直接污染价值、规模、困境溢价的量级，而不是边角料。</p><h3 id="从今天的名单往回拉-是最常见的构造错误" tabindex="-1">从今天的名单往回拉，是最常见的构造错误 <a class="header-anchor" href="#从今天的名单往回拉-是最常见的构造错误" aria-label="Permalink to &quot;从今天的名单往回拉，是最常见的构造错误&quot;">​</a></h3><p>「当前沪深 300 / 当前 S&amp;P 500 成份，取其十年历史」是教科书级的幸存者加前视：十年前它们未必在指数里，被踢出的名字带着较差路径离开样本。正确对象是每个时点的当时成份（point-in-time membership），并包含随后被剔除者在剔除前的收益。指数提供商与 CRSP 的指数文件为此存在；用今天的网页成份表回测，不是「近似」，而是换了一个总体。</p><p><span class="marginnote">ETF 与指数增强的回测特别容易中招：成份是活的，权重规则是活的，而你的程序读到的是最新一份名录。没有历史成份与权重文件，就不要报指数内策略的夏普。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>基金。</strong> 需要含已清盘、已合并产品的数据库（例如 CRSP Survivor-Bias-Free US Mutual Fund）。合并应把消失基金的业绩保留到合并日，而不是只保留存续份额类别。Elton–Gruber–Blake 强调，偏误大小取决于消失基金有多差、以及样本是否包含债券与国际品种。Carhart 等人把生存建模成与过去业绩相关的退出，从而纠正条件推断。</p><p><strong>股票。</strong> 使用全市场证券主文件，按当时是否上市、是否满足价格与成交过滤来纳入，而不是按「今天仍在市」。退市日用 Shumway 修正或交易所官方最后收益；无法补全时，至少对绩效相关退市做保守填充（例如 −30% 一类常用的破产代理，并做敏感性）。因子研究的复制（Hou–Xue–Zhang）把可投资性过滤与退市处理当成结果是否成立的一部分，而不是附录。</p><p><strong>策略产品。</strong> CTA、对冲基金数据库的自愿申报本身就是生存与回填：基金往往在一串好年景之后才进入数据库，并把那段好年景一并提交。Agarwal、Daniel 与 Naik 等文献讨论回填与生存；最低处理是剔除申报前的回填月，并保留后续清盘。</p><h3 id="偏误如何进入因子溢价" tabindex="-1">偏误如何进入因子溢价 <a class="header-anchor" href="#偏误如何进入因子溢价" aria-label="Permalink to &quot;偏误如何进入因子溢价&quot;">​</a></h3><p>价值与规模偏爱便宜、小、接近困境的名字，这些名字的退市率更高。若退市收益缺失或样本只留幸存者，多头腿被抬高。动量的输家腿同样富含随后退市的股票；若输家在退市前就被踢出回测（因为停牌、因为价格过滤用了未来最低价），空头收益会被错估。因此幸存者不是「只影响基金排名」，它改变多空的每一条腿。处理顺序应是：先构建当时可交易宇宙，再算特征，再做退市填充，最后才是排序。</p><p><span class="marginnote">价格过滤若用全样本最低价「丢掉曾经低于 1 美元的股票」，是另一种幸存者：当时可买的低价股被事后开除。过滤必须用当时价格。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>选择机制是吸收态：清盘、退市、合并一旦发生，路径从常用数据库消失。若吸收概率随负收益上升，生存样本的条件期望 \\(\\mathbb{E}[r\\mid \\text{survive}]\\) 高于无条件。这与保险里「只观察还没出险的保单」相同。Brown–Goetzmann–Ross（1995）从更一般的生存角度讨论市场本身：我们观察到的长期股权溢价，来自没有被战争、征收、关闭交易所打断的市场；这是国家层面的幸存者，量级争议更大，但逻辑同构。</p><p>对技能推断：真技能提高生存概率，于是幸存者里技能与运气更难分开。把幸存者的 t 统计量当成发现门槛，等于在已经筛选过的样本上再做一次不调整的检验，与<a href="/quant/multiple-testing-factors">多重检验</a>叠加。</p><h3 id="和回填、前视的边界" tabindex="-1">和回填、前视的边界 <a class="header-anchor" href="#和回填、前视的边界" aria-label="Permalink to &quot;和回填、前视的边界&quot;">​</a></h3><p>回填（instant history）是基金把进入数据库之前的好业绩贴进来；幸存者是进入之后仍然可能消失、而你的样本只留没消失的。前视是用了当时不可得的信息（下篇）。三者经常一起出现在同一条错误回测里：今天的成份（生存）+ 最新财务（前视）+ 基金申报前业绩（回填）。纠正必须分别做，不能只买一个「无幸存者」标签就假设 PIT 也干净。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>补退市收益会改变小样本里个别名字的权重大，价值加权比等权更稳健，但并不能取消偏差。新兴市场退市与长期停牌更不透明，填充规则的不确定性本身应进入稳健性，而不是假装有一个正确的 −30%。指数成份的历史文件有版权与质量问题，但这不能成为用今天名单的理由——那是换了一个更便宜的错误。</p><p>不要把「我们用了 CRSP 全样本」理解成无偏：CRSP 仍有退市收益缺口，Shumway 的要点恰恰是全样本文件也会偏。也不要把活下来的量化产品净值当成策略可复制性的证据：产品本身经过发行、清盘与孵化筛选。</p><p><span class="marginnote">模拟盘与实盘的差异里，有一块常被归因于成本，其实是回测宇宙比实盘更「干净」：退市、停牌、可融券名字在模拟里被静默丢掉。宇宙的日志应与成交日志一起存。</span></p>',25)),(e(),l(E,null,{default:t(()=>[h(n,{id:"mermaid-73",class:"mermaid",graph:"flowchart%20TD%0A%20%20U0%5B%22t%20%E6%97%B6%E5%88%BB%E5%8F%AF%E6%8A%95%E8%B5%84%E5%AE%87%E5%AE%99%22%5D%20--%3E%20P%5B%22%E9%9A%8F%E5%90%8E%E7%9A%84%E6%94%B6%E7%9B%8A%E8%B7%AF%E5%BE%84%22%5D%0A%20%20P%20--%3E%20S%5B%22%E6%B4%BB%E5%88%B0%20T%20%E7%9A%84%E5%AD%90%E9%9B%86%22%5D%0A%20%20P%20--%3E%20D%5B%22%E6%B8%85%E7%9B%98%20%2F%20%E9%80%80%E5%B8%82%20%2F%20%E5%89%94%E9%99%A4%22%5D%0A%20%20S%20--%3E%20UP%5B%22%E5%B9%B3%E5%9D%87%E4%B8%9A%E7%BB%A9%E5%90%91%E4%B8%8A%E5%81%8F%22%5D%0A%20%20D%20--%3E%20MISS%5B%22%E4%BA%8F%E6%8D%9F%E8%B7%AF%E5%BE%84%E7%BC%BA%E5%A4%B1%22%5D%0A%20%20MISS%20--%3E%20UP%0A%20%20PIT%5B%22%E6%97%B6%E7%82%B9%E6%88%90%E4%BB%BD%20%2B%20%E9%80%80%E5%B8%82%E5%A1%AB%E5%85%85%22%5D%20--%3E%20FIX%5B%22%E6%97%A0%E6%9D%A1%E4%BB%B6%E4%B8%9A%E7%BB%A9%22%5D%0A%20%20U0%20--%3E%20FIX%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[u(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>幸存者偏差是按「活到样本期末」筛选造成的业绩上偏，基金与股票都存在。</li><li>Brown–Goetzmann–Ibbotson–Ross、Elton–Gruber–Blake、Carhart 等人量化基金侧；Shumway 纠正 CRSP 退市收益。</li><li>用今天的指数成份回测，同时犯幸存者与前视；必须使用时点宇宙与退市处理。</li><li>价值、规模、动量的腿对退市敏感，填充规则属于研究结果的一部分。</li><li>出处：Brown, Goetzmann, Ibbotson and Ross, <em>Survivorship Bias in Performance Studies</em>, Review of Financial Studies, 1992；Shumway, <em>The Delisting Bias in CRSP Data</em>, Journal of Finance, 1997；Elton, Gruber and Blake, <em>Survivorship Bias and Mutual Fund Performance</em>, Review of Financial Studies, 1996；Carhart, Carpenter, Lynch and Musto, <em>Mutual Fund Survivorship</em>, Review of Financial Studies, 2002；Malkiel, <em>Returns from Investing in Equity Mutual Funds</em>, Journal of Finance, 1995。</li></ul>',2))])}const f=i(p,[["render",B]]);export{_ as __pageData,f as default};
